index 0a1b2c3..f4a5b6c 100644
--- a/src/paginate.ts
+++ b/src/paginate.ts
@@ -9,3 +9,15 @@ export function slicePage<T>(items: T[], page: number, size = DEFAULT_PAGE_SIZE): T[] {
   const start = (page - 1) * size;
   return items.slice(start, start + size);
 }
+
+export type Client = { query(sql: string, params: unknown[]): Promise<unknown[]> };
+
+export async function fetchPage(client: Client, page: number, size = DEFAULT_PAGE_SIZE): Promise<unknown[]> {
+  let rows: unknown[] = [];
+  try {
+    rows = await client.query("select * from items order by id limit $1 offset $2", [size, (page - 1) * size]);
+  } catch (err) {
+  }
+  return rows;
+}
